import{i as e,r as t,s as n,t as r}from"./app-FtcyK8lR.js";var i=JSON.parse(`{"path":"/guide/ui-config/export.html","title":"导出配置","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1772867174000,"contributors":[{"name":"MurphyYi","username":"MurphyYi","email":"zy84338719@hotmail.com","commits":2,"url":"https://github.com/MurphyYi"}],"changelog":[{"hash":"46a94be73dccfa2afd836e97cca5b5781eccb641","time":1772867174000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"fix: 修复文档中所有内部链接使用相对路径"},{"hash":"acf808fd844d46e164aa5b1e98e65abaf9fa76dd","time":1772854092000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"docs: 添加完整的 UI配置流程和平台对接文档"}]},"filePathRelative":"guide/ui-config/export.md"}`),a={name:`export.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="导出配置" tabindex="-1"><a class="header-anchor" href="#导出配置">#</a> 导出配置</h1><p>导出功能允许你将配置和资源打包导出，用于备份、迁移或静态部署。本指南将帮助你了解各种导出方式。</p><h2 id="概念说明" tabindex="-1"><a class="header-anchor" href="#概念说明">#</a> 概念说明</h2><h3 id="导出用途" tabindex="-1"><a class="header-anchor" href="#导出用途">#</a> 导出用途</h3><table><thead><tr><th>用途</th><th>说明</th></tr></thead><tbody><tr><td>备份</td><td>定期导出配置，防止数据丢失</td></tr><tr><td>迁移</td><td>在不同环境间迁移配置</td></tr><tr><td>静态部署</td><td>导出为 Nginx 静态站点，独立部署</td></tr><tr><td>离线使用</td><td>客户端离线时使用本地配置</td></tr></tbody></table><h3 id="导出格式" tabindex="-1"><a class="header-anchor" href="#导出格式">#</a> 导出格式</h3><p>系统支持以下导出格式：</p><ol><li><strong>JSON 文件</strong>：仅配置数据</li><li><strong>ZIP 包</strong>：配置 + 资源文件</li><li><strong>静态站点</strong>：可直接部署的 Nginx 静态包</li></ol><h2 id="快速导出" tabindex="-1"><a class="header-anchor" href="#快速导出">#</a> 快速导出</h2><h3 id="导出配置数据" tabindex="-1"><a class="header-anchor" href="#导出配置数据">#</a> 导出配置数据</h3><p><strong>通过 UI</strong>：</p><ol><li>进入 <strong>配置管理</strong> 页面</li><li>选择环境和渠道</li><li>点击 <strong>导出</strong> 按钮</li><li>选择导出格式</li><li>下载文件</li></ol><p><strong>通过 API</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 导出 JSON 配置</span></span>
<span class="line"><span class="token function">curl</span> <span class="token string">&quot;http://localhost:8080/rainbow-bridge/api/v1/runtime/config?environment_key=prod&amp;pipeline_key=main&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-o</span> config.json</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="导出完整包" tabindex="-1"><a class="header-anchor" href="#导出完整包">#</a> 导出完整包</h3><p><strong>通过 API</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 导出 ZIP 包（包含配置和资源）</span></span>
<span class="line"><span class="token function">curl</span> <span class="token string">&quot;http://localhost:8080/rainbow-bridge/api/v1/runtime/static?environment_key=prod&amp;pipeline_key=main&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-o</span> static.zip</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>ZIP 包结构</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">static.zip</span>
<span class="line">├── config.json          # 所有配置数据</span>
<span class="line">├── assets/              # 关联的资源文件</span>
<span class="line">│   ├── uuid-xxx/</span>
<span class="line">│   │   └── banner.png</span>
<span class="line">│   └── uuid-yyy/</span>
<span class="line">│       └── logo.png</span>
<span class="line">├── index.html           # 示例页面（可选）</span>
<span class="line">└── manifest.json        # 清单文件</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="选择性导出" tabindex="-1"><a class="header-anchor" href="#选择性导出">#</a> 选择性导出</h2><p>当只需要导出部分配置时，使用选择性导出功能。</p><h3 id="通过-ui" tabindex="-1"><a class="header-anchor" href="#通过-ui">#</a> 通过 UI</h3><ol><li>进入 <strong>配置迁移</strong> 页面</li><li>点击 <strong>导出选择</strong> 标签</li><li>展开环境和渠道树</li><li>勾选需要导出的配置</li><li>点击 <strong>导出选中项</strong></li><li>下载 ZIP 包</li></ol><h3 id="通过-api" tabindex="-1"><a class="header-anchor" href="#通过-api">#</a> 通过 API</h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 1. 获取导出树</span></span>
<span class="line"><span class="token function">curl</span> http://localhost:8080/rainbow-bridge/api/v1/transfer/export-tree</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 2. 选择性导出</span></span>
<span class="line"><span class="token function">curl</span> <span class="token parameter variable">-X</span> POST http://localhost:8080/rainbow-bridge/api/v1/transfer/export <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-H</span> <span class="token string">&quot;Content-Type: application/json&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-d</span> <span class="token string">&#39;{</span>
<span class="line">    &quot;selections&quot;: [</span>
<span class="line">      {</span>
<span class="line">        &quot;environment_key&quot;: &quot;prod&quot;,</span>
<span class="line">        &quot;pipeline_key&quot;: &quot;main&quot;,</span>
<span class="line">        &quot;resource_keys&quot;: [&quot;uuid-1&quot;, &quot;uuid-2&quot;]</span>
<span class="line">      }</span>
<span class="line">    ]</span>
<span class="line">  }&#39;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-o</span> export.zip</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="静态站点导出" tabindex="-1"><a class="header-anchor" href="#静态站点导出">#</a> 静态站点导出</h2><p>静态站点导出生成可直接部署的 Nginx 静态包，适用于：</p><ul><li>无需后端服务的纯前端部署</li><li>CDN 分发</li><li>离线应用场景</li></ul><h3 id="导出步骤" tabindex="-1"><a class="header-anchor" href="#导出步骤">#</a> 导出步骤</h3><ol><li>进入 <strong>导出配置</strong> 页面</li><li>选择 <strong>静态站点</strong> 模式</li><li>选择环境和渠道</li><li>配置站点信息（可选）： <ul><li>站点标题</li><li>自定义页面</li></ul></li><li>点击 <strong>生成</strong></li><li>下载 ZIP 包</li></ol><h3 id="部署静态站点" tabindex="-1"><a class="header-anchor" href="#部署静态站点">#</a> 部署静态站点</h3><p><strong>Nginx 部署</strong>：</p><div class="language-nginx line-numbers-mode" data-highlighter="prismjs" data-ext="nginx"><pre><code class="language-nginx"><span class="line"><span class="token directive"><span class="token keyword">server</span></span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token directive"><span class="token keyword">listen</span> <span class="token number">80</span></span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token directive"><span class="token keyword">server_name</span> config.example.com</span><span class="token punctuation">;</span></span>
<span class="line">    </span>
<span class="line">    <span class="token directive"><span class="token keyword">root</span> /var/www/static-config</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token directive"><span class="token keyword">index</span> index.html</span><span class="token punctuation">;</span></span>
<span class="line">    </span>
<span class="line">    <span class="token directive"><span class="token keyword">location</span> /</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token directive"><span class="token keyword">try_files</span> <span class="token variable">$uri</span> <span class="token variable">$uri</span>/ =404</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment"># 启用 gzip 压缩</span></span>
<span class="line">    <span class="token directive"><span class="token keyword">gzip</span> <span class="token boolean">on</span></span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token directive"><span class="token keyword">gzip_types</span> application/json</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>上传部署</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 解压并部署</span></span>
<span class="line"><span class="token function">unzip</span> static.zip <span class="token parameter variable">-d</span> /var/www/static-config</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 重启 Nginx</span></span>
<span class="line">nginx <span class="token parameter variable">-s</span> reload</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="导出计划" tabindex="-1"><a class="header-anchor" href="#导出计划">#</a> 导出计划</h2><h3 id="定期备份" tabindex="-1"><a class="header-anchor" href="#定期备份">#</a> 定期备份</h3><p>建议定期导出配置进行备份：</p><table><thead><tr><th>环境</th><th>备份频率</th><th>保留期限</th></tr></thead><tbody><tr><td>生产环境</td><td>每天</td><td>30 天</td></tr><tr><td>测试环境</td><td>每周</td><td>14 天</td></tr><tr><td>开发环境</td><td>按需</td><td>7 天</td></tr></tbody></table><h3 id="自动化脚本" tabindex="-1"><a class="header-anchor" href="#自动化脚本">#</a> 自动化脚本</h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token shebang important">#!/bin/bash</span></span>
<span class="line"><span class="token comment"># backup.sh - 配置备份脚本</span></span>
<span class="line"></span>
<span class="line"><span class="token assign-left variable">DATE</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">date</span> +%Y%m%d_%H%M%S<span class="token variable">)</span></span></span>
<span class="line"><span class="token assign-left variable">BACKUP_DIR</span><span class="token operator">=</span><span class="token string">&quot;/backup/rainbow-bridge&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 创建备份目录</span></span>
<span class="line"><span class="token function">mkdir</span> <span class="token parameter variable">-p</span> <span class="token variable">$BACKUP_DIR</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 导出生产环境配置</span></span>
<span class="line"><span class="token function">curl</span> <span class="token string">&quot;http://localhost:8080/rainbow-bridge/api/v1/runtime/static?environment_key=prod&amp;pipeline_key=main&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-o</span> <span class="token string">&quot;<span class="token variable">$BACKUP_DIR</span>/prod_main_<span class="token variable">$DATE</span>.zip&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 删除 30 天前的备份</span></span>
<span class="line"><span class="token function">find</span> <span class="token variable">$BACKUP_DIR</span> <span class="token parameter variable">-name</span> <span class="token string">&quot;*.zip&quot;</span> <span class="token parameter variable">-mtime</span> +30 <span class="token parameter variable">-delete</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">echo</span> <span class="token string">&quot;Backup completed: prod_main_<span class="token variable">$DATE</span>.zip&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Cron 定时任务</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 每天凌晨 2 点执行备份</span></span>
<span class="line"><span class="token number">0</span> <span class="token number">2</span> * * * /path/to/backup.sh <span class="token operator">&gt;&gt;</span> /var/log/backup.log <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span><span class="token file-descriptor important">&amp;1</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="导入配置" tabindex="-1"><a class="header-anchor" href="#导入配置">#</a> 导入配置</h2><p>导出的配置包可以通过导入功能恢复或迁移。</p><h3 id="导入预览" tabindex="-1"><a class="header-anchor" href="#导入预览">#</a> 导入预览</h3><p>导入前可以先预览，查看配置差异：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">curl</span> <span class="token parameter variable">-X</span> POST http://localhost:8080/rainbow-bridge/api/v1/transfer/import-preview <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;file=@export.zip&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;environment_key=test&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;pipeline_key=main&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>响应示例</strong>：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;code&quot;</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;message&quot;</span><span class="token operator">:</span> <span class="token string">&quot;success&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;data&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;preview&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token property">&quot;new_configs&quot;</span><span class="token operator">:</span> <span class="token number">5</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;conflict_configs&quot;</span><span class="token operator">:</span> <span class="token number">2</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;same_configs&quot;</span><span class="token operator">:</span> <span class="token number">8</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;details&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">        <span class="token punctuation">{</span></span>
<span class="line">          <span class="token property">&quot;name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;api_base_url&quot;</span><span class="token punctuation">,</span></span>
<span class="line">          <span class="token property">&quot;status&quot;</span><span class="token operator">:</span> <span class="token string">&quot;conflict&quot;</span><span class="token punctuation">,</span></span>
<span class="line">          <span class="token property">&quot;source_content&quot;</span><span class="token operator">:</span> <span class="token string">&quot;https://api.test.com&quot;</span><span class="token punctuation">,</span></span>
<span class="line">          <span class="token property">&quot;target_content&quot;</span><span class="token operator">:</span> <span class="token string">&quot;https://api.prod.com&quot;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">      <span class="token punctuation">]</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="执行导入" tabindex="-1"><a class="header-anchor" href="#执行导入">#</a> 执行导入</h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">curl</span> <span class="token parameter variable">-X</span> POST http://localhost:8080/rainbow-bridge/api/v1/transfer/import-selective <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;file=@export.zip&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;environment_key=test&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;pipeline_key=main&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;overwrite=true&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="最佳实践" tabindex="-1"><a class="header-anchor" href="#最佳实践">#</a> 最佳实践</h2><h3 id="版本命名" tabindex="-1"><a class="header-anchor" href="#版本命名">#</a> 版本命名</h3><p>导出文件使用有意义的命名：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line"># 推荐格式</span>
<span class="line">prod_main_20240307.zip      # 环境_渠道_日期</span>
<span class="line">backup_before_release.zip   # 变更说明</span>
<span class="line">v2.1.0_config.zip          # 版本号</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="变更前备份" tabindex="-1"><a class="header-anchor" href="#变更前备份">#</a> 变更前备份</h3><p>在进行重大配置变更前：</p><ol><li>导出当前配置作为备份</li><li>执行配置变更</li><li>验证变更结果</li><li>如有问题，导入备份恢复</li></ol><h3 id="多环境备份" tabindex="-1"><a class="header-anchor" href="#多环境备份">#</a> 多环境备份</h3><p>为所有环境建立备份策略：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 批量备份脚本</span></span>
<span class="line"><span class="token keyword">for</span> <span class="token for-or-select variable">env</span> <span class="token keyword">in</span> dev <span class="token builtin class-name">test</span> staging prod<span class="token punctuation">;</span> <span class="token keyword">do</span></span>
<span class="line">  <span class="token function">curl</span> <span class="token string">&quot;http://localhost:8080/rainbow-bridge/api/v1/runtime/static?environment_key=<span class="token variable">$env</span>&amp;pipeline_key=main&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">    <span class="token parameter variable">-o</span> <span class="token string">&quot;backup/<span class="token variable">\${env}</span>_main_<span class="token variable"><span class="token variable">$(</span><span class="token function">date</span> +%Y%m%d<span class="token variable">)</span></span>.zip&quot;</span></span>
<span class="line"><span class="token keyword">done</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="常见问题" tabindex="-1"><a class="header-anchor" href="#常见问题">#</a> 常见问题</h2><h3 id="q-导出的配置可以在其他系统使用吗" tabindex="-1"><a class="header-anchor" href="#q-导出的配置可以在其他系统使用吗">#</a> Q: 导出的配置可以在其他系统使用吗？</h3><p>A: 可以。导出的 JSON 格式是标准的，可以在任何支持 JSON 的系统中使用。</p><h3 id="q-静态站点支持热更新吗" tabindex="-1"><a class="header-anchor" href="#q-静态站点支持热更新吗">#</a> Q: 静态站点支持热更新吗？</h3><p>A: 不支持。静态站点是静态文件，更新后需要重新部署。如需实时更新，使用 API 接口。</p><h3 id="q-导出包中的资源链接如何处理" tabindex="-1"><a class="header-anchor" href="#q-导出包中的资源链接如何处理">#</a> Q: 导出包中的资源链接如何处理？</h3><p>A: 导出包中的资源引用会保留原始路径。部署后需要确保资源路径可访问，或修改为实际部署地址。</p><h3 id="q-导入时冲突如何处理" tabindex="-1"><a class="header-anchor" href="#q-导入时冲突如何处理">#</a> Q: 导入时冲突如何处理？</h3><p>A: 可以选择：</p><ul><li>跳过冲突配置（保留目标配置）</li><li>覆盖冲突配置（使用源配置）</li></ul><h2 id="下一步" tabindex="-1"><a class="header-anchor" href="#下一步">#</a> 下一步</h2><ul><li><a href="./migration">配置迁移</a> - 在环境间迁移配置</li><li><a href="../integration/frontend">平台对接</a> - 集成到你的项目</li></ul>`,74)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};